<?php
$status=$_GET['status']??'';$q=trim($_GET['q']??'');$where=['1=1'];$params=[];if($status!==''){$where[]='status=?';$params[]=$status;}if($q!==''){$where[]='(order_no LIKE ? OR customer_name LIKE ? OR customer_email LIKE ? OR customer_phone LIKE ?)';$like='%'.$q.'%';$params=[$like,$like,$like,$like];}
$s=db()->prepare('SELECT * FROM orders WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT 300');$s->execute($params);$rows=$s->fetchAll();
$counts=[];foreach(db()->query('SELECT status,COUNT(*) total FROM orders GROUP BY status')->fetchAll() as $r)$counts[$r['status']]=(int)$r['total'];
?>
<div class="admin-page-head"><div><span class="eyebrow">SATIŞ</span><h2>Sipariş Yönetimi</h2><p>Ödeme, teslimat, kargo takip ve durum süreçlerini tek merkezden yönetin.</p></div></div>
<div class="status-filter-tabs"><a class="<?=$status===''?'active':''?>" href="?page=orders">Tümü <b><?=array_sum($counts)?></b></a><?php foreach(['new'=>'Yeni','approved'=>'Onaylandı','preparing'=>'Hazırlanıyor','shipped'=>'Kargoda','delivered'=>'Teslim','cancelled'=>'İptal'] as $k=>$label):?><a class="<?=$status===$k?'active':''?>" href="?page=orders&status=<?=$k?>"><?=$label?> <b><?=$counts[$k]??0?></b></a><?php endforeach;?></div>
<section class="admin-card"><div class="admin-card-head"><form method="get" class="admin-searchbar"><input type="hidden" name="page" value="orders"><input type="hidden" name="status" value="<?=h($status)?>"><div class="search-control"><span>⌕</span><input name="q" value="<?=h($q)?>" placeholder="Sipariş no, müşteri, e-posta veya telefon"></div><button class="admin-btn dark">Ara</button></form><span class="pill"><?=count($rows)?> sipariş</span></div><div class="table-wrap"><table class="admin-table order-table"><thead><tr><th>Sipariş</th><th>Müşteri</th><th>Teslimat</th><th>Ödeme</th><th>Tutar</th><th>Tarih</th><th>Durum</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><?=wy_empty('Sipariş bulunamadı','Seçilen filtreye ait sipariş yok.')?></td></tr><?php endif;?><?php foreach($rows as $o):?><tr><td><a class="name" href="?page=order&id=<?=(int)$o['id']?>"><?=h($o['order_no'])?></a><small>#<?=(int)$o['id']?></small></td><td><b><?=h($o['customer_name'])?></b><small><?=h($o['customer_email'])?></small><small><?=h($o['customer_phone'])?></small></td><td><b><?=h($o['city'].' / '.$o['district'])?></b><small><?=h($o['shipping_company_name']?:$o['delivery_method'])?></small></td><td><span class="status <?=wy_status_class($o['payment_status'])?>"><?=h(wy_status_tr($o['payment_status']))?></span><small><?=h($o['payment_method']==='bank_transfer'?'Havale / EFT':$o['payment_method'])?></small></td><td><b><?=money($o['grand_total'])?></b><small>Kargo: <?=money($o['shipping_total'])?></small></td><td><?=h(date('d.m.Y',strtotime($o['created_at'])))?><small><?=h(date('H:i',strtotime($o['created_at'])))?></small></td><td><span class="status <?=wy_status_class($o['status'])?>"><?=h(wy_status_tr($o['status']))?></span></td><td><a class="admin-btn light" href="?page=order&id=<?=(int)$o['id']?>">Aç</a></td></tr><?php endforeach;?></tbody></table></div></section>